//! Federated continual context-compilation control plane.
//!
//! Atlas feature: `AFA-oracle-P03-F32`. This control plane admits only typed, scoped,
//! provenance-complete research claims and exports a digest-only certified context envelope.
//! It never invents claims, moves raw data, or makes a clinical decision.

use bioprism_foundation::{AuthorityRequirement,AutonomyTier,CapabilityManifest,Determinism,Effect,EvidenceReference,EvidenceState,ProvenanceLink,ResearchSurface,TypedPort,TypedResearchArtifact,PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID:&str="AFA-oracle-P03-F32";
pub const CONTRACT_VERSION:&str="oracle-federated-continual-context-control-plane/1.0";
pub const INPUT_SCHEMA:&str="DecisionQuery4@1";
pub const OUTPUT_SCHEMA:&str="CertifiedDecisionSection8@1";
const CONTENT_TYPE:&str="application/vnd.aurora.certified-decision-section+json";
const CHECKPOINTS:[&str;5]=["admit-typed-query","check-scope-and-evidence","check-provenance-and-replay","check-policy-and-federation","retain-omission-and-negative-receipt"];

#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]
pub struct ContextClaim { pub claim_id:String,pub proposition:String,pub scope:String,pub evidence_state:EvidenceState,pub influence_milli:u16,pub evidence_digest:Option<ContentHash>,pub provenance_digest:Option<ContentHash>,pub replay_identity:ContentHash,pub semantic_profile:String,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_result:bool,pub local_data:bool,pub permitted:bool }
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]
pub struct DecisionQuery { pub request_id:String,pub workflow_id:String,pub target_schema:String,pub purpose:String,pub semantic_profile:String,pub required_claim_order:Vec<String>,pub required_scope_order:Vec<String>,pub claims:Vec<ContextClaim>,pub replay_identity:ContentHash,pub policy_allow:bool,pub protected_closure:bool,pub signed_approval:bool,pub federation_approved:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub budget:u64,pub max_budget:u64,pub adversarial_events:Vec<String>,pub boundary:String }
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]
pub struct ContextFederationEnvelope { pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub workflow_id:String,pub target_schema:String,pub purpose:String,pub semantic_profile:String,pub disposition:String,pub claim_order:Vec<String>,pub ranked_order:Vec<String>,pub selected_order:Vec<String>,pub unresolved_order:Vec<String>,pub blocked_order:Vec<String>,pub missing_claim_order:Vec<String>,pub missing_scope_order:Vec<String>,pub omission_order:Vec<String>,pub uncertainty_order:Vec<String>,pub contradiction_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub adversarial_event_order:Vec<String>,pub checkpoint_order:Vec<String>,pub replay_identity:ContentHash,pub context_digest:ContentHash,pub artifact:TypedResearchArtifact,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String }
#[derive(Debug,Error,Clone,PartialEq,Eq)]
pub enum ContextFederationError { #[error("invalid federated context request: {0}")] Invalid(String), #[error("federated context artifact failed: {0}")] Artifact(String) }
fn invalid(v:impl Into<String>)->ContextFederationError{ContextFederationError::Invalid(v.into())}
fn canonical(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
fn digest(v:&ContentHash)->bool{v.as_str().len()==64}

pub fn context_federation_control_manifest()->CapabilityManifest{CapabilityManifest{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),capability_id:FEATURE_ID.into(),version:CONTRACT_VERSION.into(),owner_crate:"oracle".into(),consumers:["benchmark curator".into(),"federation operator".into(),"context compiler engineer".into()].into(),behavior:"operates a federated continual DecisionQuery control plane with scoped claim admission, omission certificates, and digest-only certified contexts".into(),value:"lets research consortia share certified context summaries without exporting raw preclinical observations or hiding uncertainty".into(),inputs:vec![TypedPort{name:"decision_query".into(),schema:INPUT_SCHEMA.into(),required:true}],outputs:vec![TypedPort{name:"certified_decision_section".into(),schema:OUTPUT_SCHEMA.into(),required:true}],effects:[Effect::ReadLocalData,Effect::ExecuteLocalComputation,Effect::FederationExport,Effect::WriteLocalArtifact].into(),permissions:["operate:institution-node".into()].into(),determinism:Determinism::ByteStable,evidence:vec![EvidenceReference{source_id:"opentelemetry".into(),state:EvidenceState::Supported,locator:Some("https://opentelemetry.io/docs/specs/".into())}],authority_requirements:vec![AuthorityRequirement{role:"institution node operator".into(),reason:"certified context federation requires purpose-bound institutional authorization".into()}],autonomy_tier:AutonomyTier::A2,surfaces:[ResearchSurface::Api,ResearchSurface::Protocol,ResearchSurface::Policy,ResearchSurface::Operator,ResearchSurface::Ui].into(),boundary:PRECLINICAL_BOUNDARY.into()}}

impl ContextFederationEnvelope{pub fn validate(&self)->Result<(),ContextFederationError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.contract_version!=CONTRACT_VERSION||self.feature_id!=FEATURE_ID||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.workflow_id.trim().is_empty()||self.target_schema.trim().is_empty()||self.purpose.trim().is_empty()||self.semantic_profile.trim().is_empty()||!matches!(self.disposition.as_str(),"qualified"|"unresolved"|"blocked")||self.claim_order.is_empty()||self.ranked_order.len()!=self.claim_order.len()||self.checkpoint_order!=CHECKPOINTS.map(str::to_string)||self.effect_receipts.is_empty(){return Err(invalid("federated context identity, locality, checkpoints, ranking, or effects are incomplete"));}for v in [&self.claim_order,&self.selected_order,&self.unresolved_order,&self.blocked_order,&self.missing_claim_order,&self.missing_scope_order,&self.omission_order,&self.uncertainty_order,&self.contradiction_order,&self.negative_evidence_order,&self.adversarial_event_order,&self.effect_receipts]{if !canonical(v){return Err(invalid("federated context ordering is not canonical"));}}let ids=self.claim_order.iter().collect::<BTreeSet<_>>();let parts=self.selected_order.iter().chain(self.unresolved_order.iter()).chain(self.blocked_order.iter()).collect::<Vec<_>>();if parts.len()!=ids.len()||parts.iter().any(|x|!ids.contains(x))||parts.iter().collect::<BTreeSet<_>>().len()!=parts.len()||self.ranked_order.iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("federated context states do not partition claims"));}for d in [&self.replay_identity,&self.context_digest,&self.artifact.content_hash]{if !digest(d){return Err(invalid("federated context digest is invalid"));}}self.artifact.validate_metadata().map_err(|e|ContextFederationError::Artifact(e.to_string()))?;if self.artifact.content_type!=CONTENT_TYPE{return Err(invalid("federated context artifact type is invalid"));}if self.disposition=="qualified"{if self.effect_receipts.len()!=2||self.effect_receipts[0]!=format!("exchange:permitted-summary:{}",self.request_id)||self.effect_receipts[1]!=format!("manage:local-capability:{}",self.request_id){return Err(invalid("qualified context effects are invalid"));}}else if self.effect_receipts!=["block:unsafe-release"]{return Err(invalid("non-qualified federated context must block release"));}Ok(())}}

pub fn operate_context_federation(query:&DecisionQuery)->Result<ContextFederationEnvelope,ContextFederationError>{validate_query(query)?;let mut claims=query.claims.clone();claims.sort_by(|a,b|b.influence_milli.cmp(&a.influence_milli).then(a.claim_id.cmp(&b.claim_id)));let ranked=claims.iter().map(|x|x.claim_id.clone()).collect::<Vec<_>>();let mut order=ranked.clone();order.sort();let req=query.required_claim_order.iter().cloned().collect::<BTreeSet<_>>();let missing=req.iter().filter(|x|!order.contains(x)).cloned().collect::<Vec<_>>();let scopes=query.required_scope_order.iter().cloned().collect::<BTreeSet<_>>();let mut selected=BTreeSet::new();let mut unresolved=BTreeSet::new();let mut blocked=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut contradiction=BTreeSet::new();let mut negative=BTreeSet::new();for c in &claims{if c.negative_result{negative.insert(format!("{}:negative-result",c.claim_id));}omissions.extend(c.omissions.iter().map(|x|format!("{}:{x}",c.claim_id)));uncertainty.extend(c.uncertainty.iter().map(|x|format!("{}:{x}",c.claim_id)));if c.evidence_state==EvidenceState::Contradicted{blocked.insert(c.claim_id.clone());contradiction.insert(format!("{}:contradicted-evidence",c.claim_id));continue;}if matches!(c.evidence_state,EvidenceState::Unknown|EvidenceState::Speculative){unresolved.insert(c.claim_id.clone());uncertainty.insert(format!("{}:evidence-unresolved",c.claim_id));continue;}let complete=c.proposition.trim()!=""&&scopes.contains(&c.scope)&&c.evidence_digest.is_some()&&c.provenance_digest.is_some()&&c.semantic_profile==query.semantic_profile&&c.replay_identity==query.replay_identity&&c.omissions.is_empty()&&c.uncertainty.is_empty()&&c.local_data&&c.permitted&&c.influence_milli>=700;if complete&&matches!(c.evidence_state,EvidenceState::Proven|EvidenceState::Supported){selected.insert(c.claim_id.clone());}else{unresolved.insert(c.claim_id.clone());if c.evidence_digest.is_none()||c.provenance_digest.is_none(){omissions.insert(format!("{}:evidence-or-provenance-missing",c.claim_id));}if !scopes.contains(&c.scope){omissions.insert(format!("{}:required-scope-missing",c.claim_id));}if c.influence_milli<700{uncertainty.insert(format!("{}:influence-threshold-not-met",c.claim_id));}if !c.local_data||!c.permitted{blocked.insert(c.claim_id.clone());unresolved.remove(&c.claim_id);omissions.insert(format!("{}:locality-or-permission-denied",c.claim_id));}}}for id in &missing{omissions.insert(format!("{id}:required-claim-missing"));}let missing_scope=query.required_scope_order.iter().filter(|s|!claims.iter().any(|c|&c.scope==*s)).cloned().collect::<Vec<_>>();for s in &missing_scope{omissions.insert(format!("required-scope-missing:{s}"));}negative.extend(query.adversarial_events.iter().map(|e|format!("adversarial:{e}")));let global=!query.policy_allow||!query.protected_closure||!query.signed_approval||!query.federation_approved||!query.raw_data_local||!query.aggregate_only||query.budget>query.max_budget||!query.adversarial_events.is_empty();if !query.policy_allow{uncertainty.insert("request:policy-denied".into());}if !query.protected_closure{uncertainty.insert("request:protected-closure-incomplete".into());}if !query.signed_approval||!query.federation_approved{uncertainty.insert("request:institutional-approval-incomplete".into());}if query.budget>query.max_budget{omissions.insert("request:budget-ceiling-exceeded".into());}let disposition=if global{"blocked"}else if missing.is_empty()&&missing_scope.is_empty()&&!selected.is_empty()&&unresolved.is_empty()&&blocked.is_empty(){"qualified"}else{"unresolved"};let selected=selected.into_iter().collect::<Vec<_>>();let unresolved=unresolved.into_iter().collect::<Vec<_>>();let blocked=blocked.into_iter().collect::<Vec<_>>();let omissions=omissions.into_iter().collect::<Vec<_>>();let uncertainty=uncertainty.into_iter().collect::<Vec<_>>();let contradiction=contradiction.into_iter().collect::<Vec<_>>();let negative=negative.into_iter().collect::<Vec<_>>();let adversarial=query.adversarial_events.clone();let checkpoint=CHECKPOINTS.map(str::to_string).to_vec();let effects=if disposition=="qualified"{vec![format!("exchange:permitted-summary:{}",query.request_id),format!("manage:local-capability:{}",query.request_id)]}else{vec!["block:unsafe-release".into()]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":query.request_id,"workflow_id":query.workflow_id,"target_schema":query.target_schema,"purpose":query.purpose,"semantic_profile":query.semantic_profile,"disposition":disposition,"claim_order":order,"ranked_order":ranked,"selected_order":selected,"unresolved_order":unresolved,"blocked_order":blocked,"missing_claim_order":missing,"missing_scope_order":missing_scope,"omission_order":omissions,"uncertainty_order":uncertainty,"contradiction_order":contradiction,"negative_evidence_order":negative,"adversarial_event_order":adversarial,"checkpoint_order":checkpoint,"replay_identity":query.replay_identity,"effect_receipts":effects,"raw_data_local":query.raw_data_local,"aggregate_only":query.aggregate_only,"boundary":PRECLINICAL_BOUNDARY});let context_digest=ContentHash::of_value(&payload).map_err(|e|ContextFederationError::Artifact(e.to_string()))?;let artifact=TypedResearchArtifact::from_payload(format!("oracle-certified-context:{}",query.request_id),CONTENT_TYPE,&payload,Vec::new(),vec![ProvenanceLink{source_id:format!("workflow:{}",query.workflow_id),relation:"derived-from-local-context-manifest".into(),digest:query.replay_identity.clone()}]).map_err(|e|ContextFederationError::Artifact(e.to_string()))?;let out=ContextFederationEnvelope{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:CONTRACT_VERSION.into(),feature_id:FEATURE_ID.into(),request_id:query.request_id.clone(),workflow_id:query.workflow_id.clone(),target_schema:query.target_schema.clone(),purpose:query.purpose.clone(),semantic_profile:query.semantic_profile.clone(),disposition:disposition.into(),claim_order:order,ranked_order:ranked,selected_order:selected,unresolved_order:unresolved,blocked_order:blocked,missing_claim_order:missing,missing_scope_order:missing_scope,omission_order:omissions,uncertainty_order:uncertainty,contradiction_order:contradiction,negative_evidence_order:negative,adversarial_event_order:adversarial,checkpoint_order:checkpoint,replay_identity:query.replay_identity.clone(),context_digest,artifact,effect_receipts:effects,raw_data_local:query.raw_data_local,aggregate_only:query.aggregate_only,boundary:PRECLINICAL_BOUNDARY.into()};out.validate()?;Ok(out)}

fn validate_query(q:&DecisionQuery)->Result<(),ContextFederationError>{if q.request_id.trim().is_empty()||q.workflow_id.trim().is_empty()||q.target_schema.trim().is_empty()||q.purpose.trim().is_empty()||q.semantic_profile.trim().is_empty()||q.required_claim_order.is_empty()||q.required_scope_order.is_empty()||q.claims.is_empty()||!canonical(&q.required_claim_order)||!canonical(&q.required_scope_order)||!canonical(&q.adversarial_events)||!digest(&q.replay_identity)||q.budget==0||q.max_budget==0||q.boundary!=PRECLINICAL_BOUNDARY||!q.raw_data_local||!q.aggregate_only{return Err(invalid("query identity, closure, digest, budget, locality, or boundary is invalid"));}let mut ids=BTreeSet::new();for c in &q.claims{if c.claim_id.trim().is_empty()||c.proposition.trim().is_empty()||c.scope.trim().is_empty()||!ids.insert(c.claim_id.clone())||c.influence_milli>1000||c.evidence_digest.as_ref().is_some_and(|x|!digest(x))||c.provenance_digest.as_ref().is_some_and(|x|!digest(x))||!digest(&c.replay_identity)||c.semantic_profile.trim().is_empty()||!canonical(&c.omissions)||!canonical(&c.uncertainty){return Err(invalid(format!("claim {} is malformed or duplicated",c.claim_id)));}}Ok(())}

#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn c(id:&str,state:EvidenceState,i:u16)->ContextClaim{ContextClaim{claim_id:id.into(),proposition:format!("proposition-{id}"),scope:"organoid-study".into(),evidence_state:state,influence_milli:i,evidence_digest:Some(h(&format!("evidence-{id}"))),provenance_digest:Some(h(&format!("provenance-{id}"))),replay_identity:h("replay"),semantic_profile:"preclinical-neural".into(),omissions:vec![],uncertainty:vec![],negative_result:false,local_data:true,permitted:true}}fn q(claims:Vec<ContextClaim>)->DecisionQuery{DecisionQuery{request_id:"query:context".into(),workflow_id:"workflow:context".into(),target_schema:"CertifiedDecisionSection8@1".into(),purpose:"consortium-benchmark".into(),semantic_profile:"preclinical-neural".into(),required_claim_order:vec!["claim:a".into()],required_scope_order:vec!["organoid-study".into()],claims,replay_identity:h("replay"),policy_allow:true,protected_closure:true,signed_approval:true,federation_approved:true,raw_data_local:true,aggregate_only:true,budget:4,max_budget:8,adversarial_events:vec![],boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn manifest_is_a2(){let m=context_federation_control_manifest();m.validate().unwrap();assert_eq!(m.autonomy_tier,AutonomyTier::A2)}#[test]fn qualified_exports_summary(){let r=operate_context_federation(&q(vec![c("claim:a",EvidenceState::Supported,900)])).unwrap();assert_eq!(r.disposition,"qualified");assert_eq!(r.effect_receipts.len(),2)}#[test]fn low_influence_unresolved(){let r=operate_context_federation(&q(vec![c("claim:a",EvidenceState::Supported,600)])).unwrap();assert_eq!(r.disposition,"unresolved");assert!(!r.uncertainty_order.is_empty())}#[test]fn unknown_and_contradicted_retained(){let r=operate_context_federation(&q(vec![c("claim:a",EvidenceState::Unknown,900),c("claim:b",EvidenceState::Contradicted,900)])).unwrap();assert!(r.unresolved_order.contains(&"claim:a".into()));assert!(r.blocked_order.contains(&"claim:b".into()))}#[test]fn federation_denial_blocks(){let mut x=q(vec![c("claim:a",EvidenceState::Supported,900)]);x.federation_approved=false;let r=operate_context_federation(&x).unwrap();assert_eq!(r.disposition,"blocked")}#[test]fn duplicate_rejected(){let x=q(vec![c("claim:a",EvidenceState::Supported,900),c("claim:a",EvidenceState::Supported,900)]);assert!(operate_context_federation(&x).is_err())}#[test]fn deterministic(){let a=operate_context_federation(&q(vec![c("claim:b",EvidenceState::Supported,800),c("claim:a",EvidenceState::Supported,900)])).unwrap();let b=operate_context_federation(&q(vec![c("claim:a",EvidenceState::Supported,900),c("claim:b",EvidenceState::Supported,800)])).unwrap();assert_eq!(a.ranked_order,b.ranked_order);assert_eq!(a.context_digest,b.context_digest)}}
